def safe_divide(a_text, b_text):
    try:
        a = float(a_text)
        b = float(b_text)
        result = a / b
    except ValueError:
        print(f"'{a_text}' / '{b_text}': please give numbers")
    except ZeroDivisionError as e:
        print(f"'{a_text}' / '{b_text}': error -", e)
    else:
        print(f"{a} / {b} = {result}")

safe_divide("20", "4")
safe_divide("20", "abc")
safe_divide("20", "0")

